import json
with open('appsettings-schema.json', encoding='utf-8-sig') as f:
    s = json.load(f)
found = []
def find(d, key, path=''):
    if isinstance(d, dict):
        for k, v in list(d.items()):
            kp = path + '/' + k
            if key.lower() in k.lower().replace(' ',''):
                found.append((kp, v))
            find(v, key, kp)
    elif isinstance(d, list):
        for i, v in enumerate(d):
            find(v, key, path + f'[{i}]')
find(s, 'ColorPicker')
for p, v in found[:3]:
    print(p)
    print(json.dumps(v, indent=1)[:1500])
